def cree_widgets(self):
        """Create widgets and store them in self.widgets"""
        for t in self.FIELDS:
            if type(t) is str:
                attr, kwargs = t, {}
            else:
                attr, kwargs = t[0], t[1].copy()
            self.champs.append(attr)
            is_editable = kwargs.pop("is_editable", self.is_editable)
            args = [self.acces[attr], is_editable]
            with_base = kwargs.pop("with_base", False)
            if with_base:
                args.append(self.acces.base)

            if 'with_label' in kwargs:
                label = kwargs.pop('with_label')
            else:
                label = ASSOCIATION[attr][0]
            if kwargs:
                w = ASSOCIATION[attr][3](*args, **kwargs)
            else:
                w = ASSOCIATION[attr][3](*args)

            self.widgets[attr] = (w, label)

def list_wegsegmenten_by_straat(self, straat):
        '''
        List all `wegsegmenten` in a :class:`Straat`

        :param straat: The :class:`Straat` for which the `wegsegmenten` \
                are wanted.
        :rtype: A :class:`list` of :class:`Wegsegment`
        '''
        try:
            id = straat.id
        except AttributeError:
            id = straat

        def creator():
            res = crab_gateway_request(
                self.client, 'ListWegsegmentenByStraatnaamId', id
            )
            try:
                return[
                    Wegsegment(
                        r.IdentificatorWegsegment,
                        r.StatusWegsegment
                    )for r in res.WegsegmentItem
                ]
            except AttributeError:
                return []
        if self.caches['short'].is_configured:
            key = 'ListWegsegmentenByStraatnaamId#%s' % (id)
            wegsegmenten = self.caches['short'].get_or_create(key, creator)
        else:
            wegsegmenten = creator()
        for r in wegsegmenten:
            r.set_gateway(self)
        return wegsegmenten

