def oper_set_expr(self, ctx, oper, val):
        """
        Returns the MUF needed to do an oper-assign on the lvalue. (+=, etc.)
        """
        if self.readonly:
            raise MuvError(
                "Cannot assign value to constant '%s'." % self.varname,
                position=self.position
            )
        varname = ctx.lookup_variable(self.varname)
        if varname is None:
            raise MuvError(
                "Undeclared identifier '%s'." % self.varname,
                position=self.position
            )
        if len(self.indexing) == 0:
            if ctx.assign_level > 1:
                fmt = "{var} @ {val} {oper} dup {var} !"
            else:
                fmt = "{var} @ {val} {oper} {var} !"
            return fmt.format(
                var=varname,
                oper=oper,
                val=val.generate_code(ctx),
            )
        if len(self.indexing) == 1:
            if ctx.target in ['fb7']:
                if ctx.assign_level > 1:
                    fmt = (
                        "{var} @ {idx} "
                        "over over [] {val} {oper} "
                        "dup -4 rotate "
                        "-rot ->[] pop"
                    )
                else:
                    fmt = (
                        "{var} @ {idx} "
                        "over over [] {val} {oper} "
                        "-rot ->[] pop"
                    )
            else:
                if ctx.assign_level > 1:
                    fmt = (
                        "{var} @ {idx} "
                        "over over [] {val} {oper} "
                        "dup -4 rotate "
                        "rot rot ->[] {var} !"
                    )
                else:
                    fmt = (
                        "{var} @ {idx} "
                        "over over [] {val} {oper} "
                        "rot rot ->[] {var} !"
                    )
            return fmt.format(
                var=varname,
                oper=oper,
                val=val.generate_code(ctx),
                idx=self.indexing[0].generate_code(ctx),
            )
        if ctx.target in ['fb7']:
            if ctx.assign_level > 1:
                fmt = (
                    "{var} @ {{ {sidx} }}list array_nested_get "
                    "{lidx} over over [] {val} {oper} "
                    "dup -4 rotate "
                    "-rot ->[] pop"
                )
            else:
                fmt = (
                    "{var} @ {{ {sidx} }}list array_nested_get "
                    "{lidx} over over [] {val} {oper} "
                    "-rot ->[] pop"
                )
        else:
            if ctx.assign_level > 1:
                fmt = (
                    "{var} @ {{ {idx} }}list "
                    "over over array_nested_get {val} {oper} "
                    "dup -4 rotate "
                    "rot rot array_nested_set {var} !"
                )
            else:
                fmt = (
                    "{var} @ {{ {idx} }}list "
                    "over over array_nested_get {val} {oper} "
                    "rot rot array_nested_set {var} !"
                )
        return fmt.format(
            var=varname,
            oper=oper,
            val=val.generate_code(ctx),
            idx=" ".join(
                x.generate_code(ctx)
                for x in self.indexing
            ),
            sidx=" ".join(
                x.generate_code(ctx)
                for x in self.indexing[:-1]
            ),
            lidx=self.indexing[-1].generate_code(ctx)
        )

def expand_query(config, kwds):
    """
    Expand `kwds` based on `config.search.query_expander`.

    :type config: .config.Configuration
    :type kwds: dict
    :rtype: dict
    :return: Return `kwds`, modified in place.

    """
    pattern = []
    for query in kwds.pop('pattern', []):
        expansion = config.search.alias.get(query)
        if expansion is None:
            pattern.append(query)
        else:
            parser = SafeArgumentParser()
            search_add_arguments(parser)
            ns = parser.parse_args(expansion)
            for (key, value) in vars(ns).items():
                if isinstance(value, (list, tuple)):
                    if not kwds.get(key):
                        kwds[key] = value
                    else:
                        kwds[key].extend(value)
                else:
                    kwds[key] = value
    kwds['pattern'] = pattern
    return config.search.kwds_adapter(kwds)

def is_dirty(using=None):
    """
    Returns True if the current transaction requires a commit for changes to
    happen.
    """
    if using is None:
        dirty = False
        for using in tldap.backend.connections:
            connection = tldap.backend.connections[using]
            if connection.is_dirty():
                dirty = True
        return dirty
    connection = tldap.backend.connections[using]
    return connection.is_dirty()

def mpub(self, topic, messages, binary=True):
        '''Send multiple messages to a topic. Optionally pack the messages'''
        if binary:
            # Pack and ship the data
            return self.post('mpub', data=pack(messages)[4:],
                params={'topic': topic, 'binary': True})
        elif any('\n' in m for m in messages):
            # If any of the messages has a newline, then you must use the binary
            # calling format
            raise ClientException(
                'Use `binary` flag in mpub for messages with newlines')
        else:
            return self.post(
                '/mpub', params={'topic': topic}, data='\n'.join(messages))

async def _dataobject_update_detect(self, _initialkeys, _savedresult):
        """
        Coroutine that wait for retrieved value update notification
        """
        def expr(newvalues, updatedvalues):
            if any(v.getkey() in _initialkeys for v in updatedvalues if v is not None):
                return True
            else:
                return self.shouldupdate(newvalues, updatedvalues)
        while True:
            updatedvalues, _ = await multiwaitif(_savedresult, self, expr, True)
            if not self._updatedset:
                self.scheduler.emergesend(FlowUpdaterNotification(self, FlowUpdaterNotification.DATAUPDATED))
            self._updatedset.update(updatedvalues)

