        # The context to use for rendering fields
        'TEMPLATE_FIELD_CONTEXT': {},
        # When this is False, don't do any TemplateField rendering
        'TEMPLATE_FIELD_RENDER': True
    }
    try:
        return getattr(settings, setting, defaults[setting])
    except KeyError:
        msg = "{0} is not specified in your settings".format(setting)
        raise ImproperlyConfigured(msg)

def feed(self, data):
        """
        Feed new data into this pipe.  This method is assumed to be called
        from a separate thread, so synchronization is done.

        @param data: the data to add
        @type data: str
        """
        self._lock.acquire()
        try:
            if self._event is not None:
                self._event.set()
            self._buffer.fromstring(data)
            self._cv.notifyAll()
        finally:
            self._lock.release()

def get_src_folder(self):
    """
    Gets the app source folder from settings.gradle file.

    Returns:
      A string containing the project source folder name (default is "app")
    """
    with open('%s/settings.gradle' % self.path) as f:
      for line in f.readlines():
        if line.startswith('include'):
          matches = re.findall(r'\'\:?(.+?)\'', line)
        if len(matches) == 0:
          continue
        for folder in matches:
          if self.is_app_folder(folder):
            return folder
    return 'app'

