def write_stats(stats, fname, header=None):
    """write motif statistics to text file."""
    # Write stats output to file

    for bg in list(stats.values())[0].keys():
        f = open(fname.format(bg), "w")
        if header:
            f.write(header)

        stat_keys = sorted(list(list(stats.values())[0].values())[0].keys())
        f.write("{}\t{}\n".format("Motif", "\t".join(stat_keys)))

        for motif in stats:
            m_stats = stats.get(str(motif), {}).get(bg)
            if m_stats:
                f.write("{}\t{}\n".format(
                    "_".join(motif.split("_")[:-1]),
                    "\t".join([str(m_stats[k]) for k in stat_keys])
                    ))
            else:
                logger.warn("No stats for motif {0}, skipping this motif!".format(motif.id))
            #motifs.remove(motif)
        f.close()

    return

def pipe(cls, input):
        '''
        Creates a stdin source for Sh object chains.
        :param input: If string; open as filename, if iterable, send iterated content into next command,
        if none of the above assume file like object.

        To input a string as content source, wrap in iterable:

        print 'Lines in "my_input_string":', Sh.pipe([my_string_input]) | 'wc -l'
        :return: Stdin object for chaining Sh commands after.

        WARNING: If iterable is an endless generator command evaluation will never complete.
        '''
        if type(input) in (str, unicode):
            return cls.Stdin.from_file(input)
        try:
            return cls.Stdin.from_iterator(iter(input))
        except TypeError:
            pass
        return cls.Stdin.from_file(input)

