def recv(self):
        """Receives a message from PS and decrypts it and returns a Message"""
        LOGGER.debug('Receiving')
        try:
            message_length = struct.unpack('>i', self._socket.recv(4))[0]
            message_length -= Connection.COMM_LENGTH
            LOGGER.debug('Length: %i', message_length)
        except socket.timeout:
            return None

        comm_status = struct.unpack('>i', self._socket.recv(4))[0]
        LOGGER.debug('Status: %i', comm_status)
        bytes_received = 0
        message = b""

        while bytes_received < message_length:
            if message_length - bytes_received >= 1024:
                recv_len = 1024
            else:
                recv_len = message_length - bytes_received
            bytes_received += recv_len
            LOGGER.debug('Received %i', bytes_received)
            message += self._socket.recv(recv_len)

        if comm_status == 0:
            message = self._crypt.decrypt(message)
        else:
            return Message(len(message), Connection.COMM_ERROR, message)

        msg = Message(message_length, comm_status, message)

        return msg

def compare_values(values0, values1):
    """Compares all the values of a single registry key."""
    values0 = {v[0]: v[1:] for v in values0}
    values1 = {v[0]: v[1:] for v in values1}

    created = [(k, v[0], v[1]) for k, v in values1.items() if k not in values0]
    deleted = [(k, v[0], v[1]) for k, v in values0.items() if k not in values1]
    modified = [(k, v[0], v[1]) for k, v in values0.items()
                if v != values1.get(k, None)]

    return created, deleted, modified

def _check_animation(self, last, last_level, gen):
        """Internal helper function to check the animation."""
        tmp_ = Counter()
        results = Counter()
        name, level, block = last, last_level, last
        others = False
        while name in self.ANIMATION and level >= last_level:
            if name in self.LOOP:
                if block != last:
                    count = self.check_results(tmp_)
                    if count > -1:
                        results[count] += 1
                    tmp_.clear()
                tmp_['last'] += 1

            for attribute in ('costume', 'orientation', 'position', 'size'):
                if (name, 'relative') in self.BLOCKMAPPING[attribute]:
                    tmp_[(attribute, 'relative')] += 1
                elif (name, 'absolute') in self.BLOCKMAPPING[attribute]:
                    tmp_[(attribute, 'absolute')] += 1
            if name in self.TIMING:
                tmp_['timing'] += 1

            last_level = level
            name, level, block = next(gen, ('', 0, ''))
            # allow some exceptions
            if name not in self.ANIMATION and name != '':
                if not others:
                    if block.type.shape != 'stack':
                        last_level = level
                        (name, level, block) = next(gen, ('', 0, ''))
                        others = True
        count = self.check_results(tmp_)
        if count > -1:
            results[count] += 1
        return gen, results

def get_choices_for_models():
        """
        Get the select choices for models in optgroup mode
        :return:
        """
        result = {}

        apps = [item.model.split(' - ')[0] for item in TransModelLanguage.objects.all()]
        qs = ContentType.objects.exclude(model__contains='translation').filter(app_label__in=apps).order_by(
            'app_label', 'model'
        )
        for ct in qs:
            if not issubclass(ct.model_class(), TranslatableModel):
                continue
            if ct.app_label not in result:
                result[ct.app_label] = []
            result[ct.app_label].append((
                ct.id, str(ct.model_class()._meta.verbose_name_plural)
            ))
        choices = [(str(_('Todas las clases')), (('', _('Todas las clases')),))]
        for key, value in result.items():
            choices.append((key, tuple([it for it in sorted(value, key=lambda el: el[1])])))
        return choices

def import_class(import_str):
    """Returns a class from a string including module and class."""
    mod_str, _sep, class_str = import_str.rpartition('.')
    try:
        __import__(mod_str)
        return getattr(sys.modules[mod_str], class_str)
    except (ValueError, AttributeError):
        raise ImportError('Class %s cannot be found (%s)' %
                          (class_str,
                           traceback.format_exception(*sys.exc_info())))

